import React, { useState } from 'react';
import { Link } from 'react-router-dom';

function About() {
    const [isVisible, setIsVisible] = useState(false);

    // Toggle visibility of the image and paragraph
    const toggleVisibility = () => {
        setIsVisible(!isVisible);
    };

    return (
        <>
            <div className="flex flex-col w-full min-h-screen">
                {/* Top section (Red) */}
                <div className="bg-red-600 flex flex-col items-center justify-center p-10 text-center w-full space-y-6">
                    <img
                        src="profile.avif"
                        className={`h-56 md:h-72 lg:h-80 w-auto object-cover transition-transform duration-500 ${isVisible ? 'scale-100 opacity-100' : 'scale-0 opacity-0'}`}
                        alt="Profile"
                    />
                    <span className="font-extrabold text-white text-5xl lg:text-6xl transition-all duration-500">
                        ABOUT ME
                    </span>
                    <p
                        className={`text-white text-lg max-w-3xl transition-transform duration-500 ${isVisible ? 'opacity-100' : 'opacity-0'}`}
                    >
                        I'm a communication designer who thrives on creativity and connection. I see design as a
                        way to tell stories and bring people together. When I'm not crafting visual magic, you'll
                        find me experimenting with video games, making potions in my room, or planning my next
                        travel adventure. I believe that great design starts with a spark of curiosity and a
                        dash of fun, and I can't wait to share, explore, and learn more every day!
                    </p>

                    {/* Buttons with Animation */}
                    <div className="flex flex-wrap justify-center gap-6">
                        <button
                            className="bg-black text-white px-6 py-3 hover:bg-white hover:text-black transition duration-200 w-40"
                            onClick={() => {
                                toggleVisibility();
                                window.open('https://www.linkedin.com/in/sanskriti-chauhan-1664ba33b/', '_blank');
                            }}
                        >
                            LinkedIn
                        </button>

                        <button
                            className="bg-black text-white px-6 py-3 hover:bg-white hover:text-black transition duration-200 w-40"
                            onClick={() => {
                                toggleVisibility();
                                window.open('mailto:sanskritichauhan1234@gmail.com', '_blank');
                            }}
                        >
                            Email
                        </button>

                        <button
                            className="bg-black text-white px-6 py-3 hover:bg-white hover:text-black transition duration-200 w-40"
                            onClick={() => {
                                toggleVisibility();
                                window.open('https://drive.google.com/file/d/1cypZb0AmTxQRITlIiSJg0oULeFkyDBw4/view', '_blank');
                            }}
                        >
                            Portfolio
                        </button>
                    </div>
                </div>

                {/* Bottom section (Black) */}
                <div className="bg-black flex flex-col items-center justify-center text-white w-full min-h-screen p-10 space-y-6">
                    {/* Contact Section */}
                    <div className="flex justify-evenly w-full max-w-3xl">
                        {/* Personal Contact List */}
                        <ul className="space-y-2">
                            <li className="text-lg font-semibold">CONTACT</li>
                            <li><a href="mailto:sanskritichauhan1234@gmail.com" className="hover:underline">sanskritichauhan1234@gmail.com</a></li>
                            <li><a href="tel:+919867067656" className="hover:underline">+91 9867067656</a></li>
                        </ul>

                        {/* Navigation Links */}
                        <nav className="mt-4">
                            <ul className="flex flex-col items-center space-y-4">
                                <Link to="/" className="text-lg hover:underline">HOME</Link>
                                <Link to="/about" className="text-lg hover:underline">ABOUT</Link>
                                <Link to="/portfolio" className="text-lg hover:underline">PORTFOLIO</Link>
                                <Link to="/photography" className="text-lg hover:underline">PHOTOGRAPHY</Link>
                            </ul>
                        </nav>
                    </div>

                    {/* Name Display with Animation */}
                    <div className={`mt-6 text-center transition-all duration-500 ${isVisible ? 'opacity-100' : 'opacity-0'}`}>
                        <span className="font-extrabold text-4xl lg:text-5xl whitespace-nowrap block">SANSKRITI CHAUHAN</span>
                    </div>
                </div>
            </div>
        </>
    );
}

export default About;
